"""Snap span edges to a fixed step for payroll."""

from hourglass.parsing import format_span
from hourglass.models import Span


def _snap(minute, step):
    return (minute + step // 2) // step * step


def _rounded(span, step):
    return Span(
        _snap(span.start, step), _snap(span.end, step)
    )


def _label(span):
    hours, mins = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {mins}m)"


# ---
def round_spans(spans, step):
    """Snap edges to the nearest step, label each span."""
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step}")
    return [
        _label(_rounded(span, step))
        for span in spans
    ]

